[CmdletBinding()]
param(
    [switch] $DryRun,
    [switch] $SkipTests
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$commonScript = Join-Path -Path $PSScriptRoot -ChildPath 'Phase2.Common.ps1'

if (-not (Test-Path -LiteralPath $commonScript)) {
    throw "File condiviso non trovato: $commonScript"
}

. $commonScript

function Write-Base64File {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string] $Path,

        [Parameter(Mandatory)]
        [string] $Base64,

        [switch] $DryRun
    )

    if ($DryRun) {
        Write-Host "[DryRun] Scriverebbe: $Path"
        return
    }

    $directory = Split-Path -Path $Path -Parent

    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }

    $normalizedBase64 = $Base64 -replace '\s', ''
    $bytes = [Convert]::FromBase64String($normalizedBase64)
    [System.IO.File]::WriteAllBytes($Path, $bytes)
    Write-Host "File scritto: $Path"
}

$repositoryRoot = Get-RepositoryRoot
$webRoot = Join-Path $repositoryRoot 'apps\web'
$nextBuildDirectory = Join-Path $webRoot '.next'

Write-Step -Message 'Preflight Fase 09 esperienza pubblica'

Assert-RepoRoot -Path $repositoryRoot
Assert-Command -Name 'node'

$npmCommand = if ($env:OS -eq 'Windows_NT') {
    'npm.cmd'
}
else {
    'npm'
}

$npxCommand = if ($env:OS -eq 'Windows_NT') {
    'npx.cmd'
}
else {
    'npx'
}

Assert-Command -Name $npmCommand
Assert-Command -Name $npxCommand
Assert-NoWorkflowChanges -RepositoryRoot $repositoryRoot

$phase8Requirements = @(
    'apps\web\components\control-center\notification.tsx',
    'apps\web\lib\control-center\event-form-validation.ts',
    'apps\api\src\reservations\public-reservations.controller.ts',
    'apps\api\src\reservations\reservation-stripe.controller.ts'
)

foreach ($relativePath in $phase8Requirements) {
    $requiredPath = Join-Path $repositoryRoot $relativePath

    if (-not (Test-Path -LiteralPath $requiredPath)) {
        throw "Prerequisito Fase 08/booking mancante: $requiredPath"
    }
}

