if ($DryRun) {
    Write-Step -Message 'DryRun Fase 09 completato'

    Write-Host @"
La Fase 09 genererebbe 33 file:

- catalogo pubblico eventi e dettaglio evento;
- ricerca per testo e città;
- disponibilità, hold e assegnazione tavolo;
- conversione hold in prenotazione;
- Stripe Checkout con pagine success/cancel;
- conferma pubblica tramite reservation token;
- BFF Next.js per tutte le chiamate pubbliche;
- test backend e frontend;
- nessuna migrazione database.
"@

    return
}

Write-Step -Message 'Formattazione backend Fase 09'

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'apps/api/src/events/dto/public-event-list-query.dto.ts',
        'apps/api/src/events/public-event-policy.ts',
        'apps/api/src/events/public-event-policy.spec.ts',
        'apps/api/src/events/public-events.service.ts',
        'apps/api/src/events/public-events.controller.ts',
        'apps/api/src/events/events.module.ts'
    ) `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Formattazione frontend Fase 09'

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'app/(public)/page.tsx',
        'app/(public)/events/page.tsx',
        'app/(public)/events/[slug]/page.tsx',
        'app/(public)/booking/[reservationToken]/page.tsx',
        'app/(public)/booking/success/page.tsx',
        'app/(public)/booking/cancel/page.tsx',
        'app/api/public/**/*.ts',
        'components/public/**/*.tsx',
        'lib/api/public-bff.ts',
        'lib/public-booking/**/*.ts',
        'app/globals.css'
    ) `
    -WorkingDirectory $webRoot | ForEach-Object {
        Write-Host $_
    }

Invoke-Checked `
    -FilePath $npxCommand `
    -ArgumentList @(
        'prettier',
        '--write',
        'scripts/verify-phase-9-public-booking.mjs',
        'docs/phase-2/public-booking-experience.md'
    ) `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Verifica strutturale Fase 09'

