    -FilePath 'node' `
    -ArgumentList @('scripts/verify-phase-9-public-booking.mjs') `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

$localBootstrapPath = Join-Path `
    -Path $repositoryRoot `
    -ChildPath 'scripts\bootstrap-platform-admin.local.ts'

if (Test-Path -LiteralPath $localBootstrapPath) {
    Write-Step -Message 'Formattazione helper bootstrap locale'

    Invoke-Checked `
        -FilePath $npxCommand `
        -ArgumentList @(
            'prettier',
            '--write',
            'scripts/bootstrap-platform-admin.local.ts'
        ) `
        -WorkingDirectory $repositoryRoot | ForEach-Object {
            Write-Host $_
        }
}

Write-Step -Message 'Lint backend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'lint') `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

if (-not $SkipTests) {
    Write-Step -Message 'Test backend'

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('test') `
        -WorkingDirectory $repositoryRoot | ForEach-Object {
            Write-Host $_
        }
}

Write-Step -Message 'Build backend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'build') `
    -WorkingDirectory $repositoryRoot | ForEach-Object {
        Write-Host $_
    }

Write-Step -Message 'Lint frontend'

Invoke-Checked `
    -FilePath $npmCommand `
    -ArgumentList @('run', 'lint') `
    -WorkingDirectory $webRoot | ForEach-Object {
        Write-Host $_
    }

if (-not $SkipTests) {
    Write-Step -Message 'Test frontend'

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('run', 'test') `
        -WorkingDirectory $webRoot | ForEach-Object {
            Write-Host $_
        }
}

$hadNodeEnvironment = Test-Path Env:NODE_ENV
$previousNodeEnvironment = if ($hadNodeEnvironment) {
    $env:NODE_ENV
}
else {
    $null
}

try {
    Write-Step -Message 'Build Next.js pulito'

    $env:NODE_ENV = 'production'

    if (Test-Path -LiteralPath $nextBuildDirectory) {
        Remove-Item `
            -LiteralPath $nextBuildDirectory `
            -Recurse `
            -Force
        Write-Host "Cache Next.js rimossa: $nextBuildDirectory"
    }

    Invoke-Checked `
        -FilePath $npmCommand `
        -ArgumentList @('run', 'build') `
        -WorkingDirectory $webRoot | ForEach-Object {
            Write-Host $_
        }
}
finally {
    if ($hadNodeEnvironment) {
        $env:NODE_ENV = $previousNodeEnvironment
    }
    else {
        Remove-Item Env:NODE_ENV -ErrorAction SilentlyContinue
    }
}

Assert-NoWorkflowChanges -RepositoryRoot $repositoryRoot
Show-GitDiffSummary -RepositoryRoot $repositoryRoot

Write-Step -Message 'Fase 09 completata'
